async () => {
const txt = (s) => (s || '').replace(/\s+/g, ' ').trim();
const wait = (ms) => new Promise((r) => setTimeout(r, ms));
const shown = (scope) => [...scope.querySelectorAll('button[class*=selectButton]')].map((b) => txt(b.getAttribute('aria-label')));
const groups = (scope) => [...scope.querySelectorAll('[class*=groupTitle]')].map((e) => txt(e.innerText));
const open = async (scope) => { scope.querySelector('button[aria-haspopup=listbox]').click(); await wait(500); return [...document.querySelectorAll('[role=listbox][aria-label=Material]')].pop(); };
const close = async () => { document.body.dispatchEvent(new MouseEvent('mousedown', { bubbles: true })); await wait(300); };
const labels = (lb) => [...lb.querySelectorAll('[role=option]')].map((o) => txt(o.innerText));
const pick = async (scope, text, expand) => {
  const lb = await open(scope);
  if (!lb) return { err: 'NO LISTBOX' };
  if (expand) { const caret = lb.querySelector(`button[aria-label="Expand ${expand}"]`); if (!caret) { await close(); return { err: 'NO CARET ' + expand, offered: labels(lb) }; } caret.click(); await wait(300); }
  const btn = [...lb.querySelectorAll('button')].find((b) => txt(b.innerText) === text);
  if (!btn) { await close(); return { err: 'NO ITEM ' + text, offered: labels(lb) }; }
  btn.click(); await wait(900);
  const names = shown(scope);
  return { pick: text, count: names.length, swatches: names.length <= 4 ? names : undefined, groups: groups(scope) };
};
const panelOf = async (title) => {
  const trig = [...document.querySelectorAll('button')].find((b) => txt(b.innerText) === title && b.hasAttribute('aria-expanded'));
  if (!trig) return null;
  if (trig.getAttribute('aria-expanded') !== 'true') { trig.scrollIntoView({ block: 'center' }); trig.click(); await wait(800); }
  return document.getElementById(trig.getAttribute('aria-controls') || '');
};

const panel = await panelOf('Countertop Color');
if (!panel) return { err: 'NO COUNTERTOP COLOR PANEL' };
const result = { initialGroups: groups(panel), initialCount: shown(panel).length };
let lb = await open(panel);
result.menu = labels(lb);
const caret = lb.querySelector('button[aria-label="Expand Solid Surface"]');
result.solidSurfaceIsHeader = !!caret;
if (caret) { caret.click(); await wait(300); result.menuExpanded = labels(lb); }
await close();
result.technolite = await pick(panel, 'Technolite', 'Solid Surface');
result.technomat = await pick(panel, 'Technomat', 'Solid Surface');
result.header = await pick(panel, 'Solid Surface');
result.glass = await pick(panel, 'Glass');
result.showAll = await pick(panel, 'Show all');
lb = await open(panel); lb?.querySelector('button[aria-label="Expand Solid Surface"]')?.click(); await wait(400);
return result;
}

